#!/usr/bin/env python3
"""Generates the 8x16 font of the test kernel from a system TrueType font.

Usage: scripts/gen_font.py [--font PATH] [--size PIXELS] [--check]
  --font   TrueType font (default: DejaVu Sans Mono)
  --size   font size in pixels used for rendering (default: 13)
  --check  do not write; fail if one of the generated files differs from
           what this script would produce (used to detect hand edits)

Writes tests/qemu/test_kernel/font8x16.c, src/boot/diagnostic_font.c, and src/boot/boot_ui_font.c (the same glyphs): one 16-byte bitmap for every printable
ASCII character 0x20..0x7E. Each byte is one pixel row, the most significant bit
is the leftmost pixel; a set bit is a lit pixel. The output is deterministic for
a given font file and size.

The default font, DejaVu Sans Mono, is free software (the Bitstream Vera and
DejaVu license allows copying and changing it, including inside generated data,
if the license text is kept with copies of the font itself). Liberation Mono
(SIL Open Font License) also works with --font.
"""

import argparse
import pathlib
import sys

from PIL import Image, ImageDraw, ImageFont

CELL_WIDTH = 8
CELL_HEIGHT = 16
FIRST = 0x20
LAST = 0x7E
THRESHOLD = 110          # gray level (0..255) from which a pixel is lit
DEFAULT_FONT = "/usr/share/fonts/TTF/DejaVuSansMono.ttf"
DEFAULT_SIZE = 13

ROOT = pathlib.Path(__file__).resolve().parent.parent
OUTPUT = ROOT / "tests" / "qemu" / "test_kernel" / "font8x16.c"
DIAGNOSTIC_OUTPUT = ROOT / "src" / "boot" / "diagnostic_font.c"
BOOT_UI_OUTPUT = ROOT / "src" / "boot" / "boot_ui_font.c"

# The three generated files: the font of the test kernel, the font of Stage 3, and the font of the Stage 4
# menu (the same glyphs, different names).
TARGETS = [
    dict(path=OUTPUT, title="font8x16.c - 8x16 bitmap font of the test kernel (printable ASCII).",
         include="font.h", symbol="jp_test_font8x16",
         count="JP_TEST_FONT_GLYPH_COUNT", height="JP_TEST_FONT_HEIGHT"),
    dict(path=DIAGNOSTIC_OUTPUT, title="diagnostic_font.c - 8x16 bitmap font of the Stage 3 diagnostic output (printable ASCII).",
         include="diagnostic_font.h", symbol="jp_diagnostic_font8x16",
         count="JP_DIAGNOSTIC_FONT_GLYPH_COUNT", height="JP_DIAGNOSTIC_FONT_HEIGHT"),
    dict(path=BOOT_UI_OUTPUT, title="boot_ui_font.c - 8x16 bitmap font of the Stage 4 boot menu (printable ASCII).",
         include="boot_ui_font.h", symbol="jp_boot_ui_font8x16",
         count="JP_BOOT_UI_FONT_GLYPH_COUNT", height="JP_BOOT_UI_FONT_HEIGHT"),
]


def render(font: ImageFont.FreeTypeFont, char: str) -> list[int]:
    ascent, descent = font.getmetrics()
    top = (CELL_HEIGHT - (ascent + descent)) // 2
    image = Image.new("L", (CELL_WIDTH, CELL_HEIGHT), 0)
    draw = ImageDraw.Draw(image)
    # Center horizontally: the advance of a monospace font is about one cell.
    advance = font.getlength(char)
    left = int(round((CELL_WIDTH - advance) / 2))
    draw.text((left, top), char, font=font, fill=255)
    rows = []
    for y in range(CELL_HEIGHT):
        row = 0
        for x in range(CELL_WIDTH):
            row <<= 1
            if image.getpixel((x, y)) >= THRESHOLD:
                row |= 1
        rows.append(row)
    return rows


def build(font_path: str, size: int, target: dict) -> str:
    font = ImageFont.truetype(font_path, size)
    lines = [
        "/*",
        " * " + target["title"],
        " *",
        " * GENERATED by scripts/gen_font.py from %s at %d px." % (pathlib.Path(font_path).name, size),
        " * Do not edit by hand: change the script and generate again.",
        " * Each glyph is 16 rows; the most significant bit of a row is the leftmost pixel.",
        " */",
        "",
        '#include "%s"' % target["include"],
        "",
        "const uint8_t %s[%s][%s] = {" % (target["symbol"], target["count"], target["height"]),
    ]
    for code in range(FIRST, LAST + 1):
        rows = render(font, chr(code))
        label = chr(code) if chr(code) not in "\\*/" else "(%d)" % code
        values = ", ".join("0x%02X" % row for row in rows)
        lines.append("\t{ %s }, /* 0x%02X %s */" % (values, code, label))
    lines.append("};")
    lines.append("")
    return "\n".join(lines)


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--font", default=DEFAULT_FONT)
    parser.add_argument("--size", type=int, default=DEFAULT_SIZE)
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()

    status = 0
    for target in TARGETS:
        text = build(args.font, args.size, target)
        name = target["path"].name
        if args.check:
            if not target["path"].exists() or target["path"].read_text() != text:
                print(name, "differs from the generated output", file=sys.stderr)
                status = 1
            else:
                print(name, "is up to date")
        else:
            target["path"].write_text(text)
            print("written", target["path"])
    return status


if __name__ == "__main__":
    sys.exit(main())
